<?php
namespace App\Notifications;
use App\Models\Pembayaran; use App\Filament\Admin\Resources\Pembayarans\PembayaranResource; use Filament\Actions\Action; use Filament\Notifications\Notification as FilamentNotification; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification;
class PembayaranDiperbarui extends Notification { use Queueable; public function __construct(public Pembayaran $pembayaran, public bool $disetujui, public ?string $alasan=null){} public function via(object $notifiable):array{return ['database'];} public function toDatabase(object $notifiable):array{ $no='PAY-'.str_pad((string)$this->pembayaran->id,5,'0',STR_PAD_LEFT); $title=$this->disetujui?'Pembayaran Disetujui Supplier':'Pembayaran Ditolak Supplier'; $body=$this->disetujui?"{$no} telah disetujui supplier dan sekarang diperhitungkan sebagai pembayaran sah.":"{$no} ditolak supplier. Alasan: {$this->alasan}. Silakan tindak lanjuti."; return FilamentNotification::make()->title($title)->body($body)->icon($this->disetujui?'heroicon-o-check-circle':'heroicon-o-x-circle')->iconColor($this->disetujui?'success':'danger')->actions([Action::make('lihat')->label('Lihat Pembayaran')->url(PembayaranResource::getUrl('view',['record'=>$this->pembayaran->getKey()]))])->getDatabaseMessage(); } }
